@Entity(tableName = "game")
public class Game implements Serializable {
    @PrimaryKey(autoGenerate = true)
    private int gameId;
    private String name;
    private String slug;
    private String released;
    private String rating;
    private String background_image;
    private String platforms;
    public Game() {
    }
