        for (int axon = 0; axon < AXONS; axon++) {
            if (input_spike[core][axon] == '1') {
                enqueue(&cores[core].spikeQueue, axon);
            }
        }
        printf("Queue for Core %d:\n", core);
        printQueue(&cores[core].spikeQueue);
    }
}
