bool Volume::loadFromFiles(const std::vector<std::string> &paths) {
    /*
     * Loads a 3D volume from multiple image files
     *
     * This member function of the Volume class loads a series of images from the specified file paths to construct a 3D
     * volume. The images are assumed to have the same dimensions and number of channels. The function initializes the
     * volume's depth based on the number of paths provided, checks if at least one path is provided, and then loads each
     * image in sequence. The images are concatenated into a single data buffer representing the 3D volume. If any image
     * fails to load, or if memory allocation for the entire volume data fails, it prints an error message to standard error
     * and cleans up any allocated resources.
     *
     * @param paths: A vector of strings representing the paths to the image files that comprise the volume.
     *
     * @return: A boolean value indicating the success (true) or failure (false) of loading the volume.
     */
    std::cout << "Loading volume from " << paths.size() << " files..." << std::endl;
    depth = paths.size();
    if (depth == 0) {
        std::cerr << "Error: No paths provided for volume loading." << std::endl;
        return false;
    }
    int channels;
    // Assuming all images have the same size and number of channels
    data = stbi_load(paths[0].c_str(), &width, &height, &channels, 0);
    if (!data) {
        std::cerr << "Error loading volume slice: " << paths[0] << std::endl;
        return false;
    }
    size_t sliceSize = width * height * channels;
    unsigned char *volumeData = (unsigned char *) malloc(sliceSize * depth);
    if (!volumeData) {
        std::cerr << "Failed to allocate memory for volume data." << std::endl;
        return false;
    }
    memcpy(volumeData, data, sliceSize);
    stbi_image_free(data);
    for (int i = 1; i < depth; ++i) {
        data = stbi_load(paths[i].c_str(), &width, &height, &channels, 0);
        if (!data) {
            std::cerr << "Error loading volume slice: " << paths[i] << std::endl;
            free(volumeData);
            return false;
        }
        memcpy(volumeData + sliceSize * i, data, sliceSize);
        stbi_image_free(data);
    }
    data = volumeData;
    std::cout << "Volume loaded with size " << width << " x " << height << " x " << depth << " with " << channels << " channel(s)." << std::endl;
    return true;
}
bool Volume::loadFromDirectory(const std::string &directoryPath) {
    std::vector<std::string> paths;
    // Iterate over the directory and add the paths of all regular files to the vector
    try {
        for (const auto &entry: fs::directory_iterator(directoryPath)) {
            if (entry.is_regular_file()) {
                paths.push_back(entry.path().string());
            }
        }
    } catch (const fs::filesystem_error &e) {
        std::cerr << "Filesystem error: " << e.what() << std::endl;
        return false;
    }
    // Make sure at least one image file was found
    if (paths.empty()) {
        std::cerr << "Error: No image files found in the provided directory." << std::endl;
        return false;
    }
    // Sort the paths to ensure the images are loaded in the correct order
//    std::sort(paths.begin(), paths.end());
    // Sort the paths to ensure the images are loaded in the correct order
    quickSort(paths, 0, paths.size() - 1);
    // Use the loadFromFiles member function to load the volume from the collected paths
    return loadFromFiles(paths);
}
std::vector<unsigned char> Volume::getPlaneSlice(const std::string& plane, int sliceIndex) const {
    std::vector<unsigned char> slice;
    if (plane == "x-y" && sliceIndex <= depth) {
        slice = getSliceData(sliceIndex - 1); // Assuming sliceIndex starts from 1
    } else if (plane == "x-z" || plane == "y-z") {
        int sliceWidth = (plane == "x-z") ? width : height;
        int sliceHeight = (plane == "x-z") ? depth : depth;
        slice.resize(sliceWidth * sliceHeight);
        for (int z = 0; z < depth; ++z) {
            for (int y = 0; y < height; ++y) {
                for (int x = 0; x < width; ++x) {
                    if (plane == "x-z" && y == sliceIndex - 1) {
                        slice[z * sliceWidth + x] = data[z * width * height + y * width + x];
                    } else if (plane == "y-z" && x == sliceIndex - 1) {
                        slice[z * sliceWidth + y] = data[z * width * height + y * width + x];
                    }
                }
            }
        }
    } else {
        std::cerr << "Invalid plane or slice index." << std::endl;
    }
    return slice;
}
void Volume::quickSort(std::vector<std::string>& arr, int low, int high) {
    if (low < high) {
        int pi = partition(arr, low, high);
        quickSort(arr, low, pi - 1);
        quickSort(arr, pi + 1, high);
    }
}
int Volume::partition(std::vector<std::string>& arr, int low, int high) {
    std::string pivot = arr[high];
    int i = (low - 1);
    for (int j = low; j <= high - 1; j++) {
        if (arr[j] < pivot) {
            i++;
            std::swap(arr[i], arr[j]);
        }
    }
    std::swap(arr[i + 1], arr[high]);
    return (i + 1);
}
