bool Volume::loadFromFiles(const std::vector<std::string> &paths) {
    /*
     * Loads a 3D volume from multiple image files
     *
     * This member function of the Volume class loads a series of images from the specified file paths to construct a 3D
     * volume. The images are assumed to have the same dimensions and number of channels. The function initializes the
     * volume's depth based on the number of paths provided, checks if at least one path is provided, and then loads each
     * image in sequence. The images are concatenated into a single data buffer representing the 3D volume. If any image
     * fails to load, or if memory allocation for the entire volume data fails, it prints an error message to standard error
     * and cleans up any allocated resources.
     *
     * @param paths: A vector of strings representing the paths to the image files that comprise the volume.
     *
     * @return: A boolean value indicating the success (true) or failure (false) of loading the volume.
     */
    std::cout << "Loading volume from " << paths.size() << " files..." << std::endl;
    depth = paths.size();
    if (depth == 0) {
        std::cerr << "Error: No paths provided for volume loading." << std::endl;
        return false;
    }
    int channels;
    // Assuming all images have the same size and number of channels
    data = stbi_load(paths[0].c_str(), &width, &height, &channels, 0);
    if (!data) {
        std::cerr << "Error loading volume slice: " << paths[0] << std::endl;
        return false;
    }
    size_t sliceSize = width * height * channels;
    unsigned char *volumeData = (unsigned char *) malloc(sliceSize * depth);
    if (!volumeData) {
        std::cerr << "Failed to allocate memory for volume data." << std::endl;
        return false;
    }
    memcpy(volumeData, data, sliceSize);
    stbi_image_free(data);
    for (int i = 1; i < depth; ++i) {
        data = stbi_load(paths[i].c_str(), &width, &height, &channels, 0);
        if (!data) {
            std::cerr << "Error loading volume slice: " << paths[i] << std::endl;
            free(volumeData);
            return false;
        }
        memcpy(volumeData + sliceSize * i, data, sliceSize);
        stbi_image_free(data);
    }
    data = volumeData;
    std::cout << "Volume loaded with size " << width << " x " << height << " x " << depth << " with " << channels
              << " channel(s)." << std::endl;
    return true;
}
