Gaussian3DFilter::Gaussian3DFilter(double sigma, int kernelSize) : sigma(sigma), kernelSize(kernelSize) {}
std::vector<double> Gaussian3DFilter::computeGaussian1DKernel() const {
    /*
     * Computes a 1D Gaussian kernel
     *
     * This member function calculates the coefficients of a 1D Gaussian kernel based on the current kernel size and sigma
     * (standard deviation) of the Gaussian3DFilter class. The kernel is symmetric and centered around zero. Each coefficient
     * is calculated using the Gaussian function e^(-(x^2)/(2*sigma^2)), then normalized so that the sum of all coefficients
     * equals 1. This normalization ensures that applying the kernel to a signal does not change the signal's amplitude.
     *
     * @return: A vector of doubles containing the normalized coefficients of the 1D Gaussian kernel.
     */
    std::vector<double> kernel(kernelSize);
    int halfSize = kernelSize / 2;
    double sum = 0.0;
    double factor = 1.0 / (sqrt(2.0f * M_PI) * sigma);
    for (int i = -halfSize; i <= halfSize; ++i) {
        kernel[i + halfSize] = factor * exp(-(i * i) / (2.0f * sigma * sigma));
        sum += kernel[i + halfSize];
    }
    // Normalize kernel
    for (auto &value: kernel) {
        value /= sum;
    }
    return kernel;
}
void Gaussian3DFilter::applyGaussian1DFilter_X(std::vector<unsigned char> &data, int width, int height, int depth) {
    auto kernel = computeGaussian1DKernel();
    int halfSize = kernelSize / 2;
    std::vector<unsigned char> temp(data.size(), 0);
    for (int z = 0; z < depth; ++z) {
        for (int y = 0; y < height; ++y) {
            for (int x = 0; x < width; ++x) {
                double weightedSum = 0.0;
                for (int k = -halfSize; k <= halfSize; ++k) {
                    int xk = std::max(0, std::min(x + k, width - 1));
                    weightedSum +=
                            static_cast<double>(data[z * width * height + y * width + xk]) * kernel[k + halfSize];
                }
                temp[z * width * height + y * width + x] = static_cast<unsigned char>(std::max(0.0, std::min(255.0,
                                                                                                             std::round(
                                                                                                                     weightedSum))));
            }
        }
    }
    data = std::move(temp);
}
