        memcpy(volumeData + sliceSize * i, data, sliceSize);
        stbi_image_free(data);
    }
    data = volumeData;
    std::cout << "Volume loaded with size " << width << " x " << height << " x " << depth << " with " << channels
              << " channel(s)." << std::endl;
    return true;
}
bool Volume::loadFromDirectory(const std::string &directoryPath) {
    /**
     * Loads a 3D volume from image files located in a specified directory
     *
     * This member function of the Volume class loads a series of image files from a given directory to construct a 3D volume.
     * It iterates through the directory, collecting paths of all regular files. These paths are then sorted to ensure that
     * the images are loaded in the correct order, which is crucial for correctly assembling the 3D volume. The function
     * leverages the loadFromFiles member function to load the images into the volume. If the directory cannot be read
     * or contains no image files, the function prints an error message and returns false.
     *
     * @param directoryPath: A string representing the path to the directory containing the image files to be loaded.
     *
     * @return: A boolean value indicating the success (true) or failure (false) of loading the volume from the directory.
     */
    std::vector<std::string> paths;
    // Iterate over the directory and add the paths of all regular files to the vector
    try {
        for (const auto &entry: fs::directory_iterator(directoryPath)) {
            if (entry.is_regular_file()) {
                paths.push_back(entry.path().string());
            }
        }
    } catch (const fs::filesystem_error &e) {
        std::cerr << "Filesystem error: " << e.what() << std::endl;
        return false;
    }
    // Make sure at least one image file was found
    if (paths.empty()) {
        std::cerr << "Error: No image files found in the provided directory." << std::endl;
        return false;
    }
    // Sort the paths to ensure the images are loaded in the correct order
    Algorithm::quickSort(paths, 0, paths.size() - 1);
    // Use the loadFromFiles member function to load the volume from the collected paths
    return loadFromFiles(paths);
}
void Volume::save(const std::string &path, const std::string &plane,
                  std::optional<std::variant<int, std::string>> option) const {
    /**
     * Saves slices or projections of the 3D volume to files
     *
     * This member function of the Volume class saves slices or projections of the 3D volume data based on the specified plane
     * and option. The plane can be 'x-y', 'x-z', or 'y-z'. The function supports saving a single slice, multiple slices, or specific
     * projections such as Maximum Intensity Projection (MIP), Minimum Intensity Projection (MinIP), Average Intensity Projection (AIP),
     * or Median Intensity Projection (MedIP), depending on the provided option. If the option is an integer, it saves the corresponding
     * slice. If the option is a string, it saves the specified projection. If no option is provided, it defaults to saving all slices
     * along the specified plane. The function checks for valid inputs and handles the creation of the output directory if it does not
     * exist. It utilizes the filesystem (fs) library for directory operations and the stb_image_write library for saving images.
     *
     * @param path: A string representing the output directory where the slices or projections will be saved.
     * @param plane: A string specifying the plane of the slices or projections ('x-y', 'x-z', 'y-z').
     * @param option: An optional parameter that can be either an integer (for specifying a slice index) or a string
     *                (for specifying the type of projection). If std::nullopt, all slices will be saved.
     *
     * @return: None
     */
    // Check if the plane is valid
    if (plane != "x-y" && plane != "x-z" && plane != "y-z") {
        std::cerr << "Invalid plane specified. Valid planes are 'x-y', 'x-z', and 'y-z'." << std::endl;
        return;
    }
    // If an option is provided, check if it is valid
    if (option && std::holds_alternative<std::string>(option.value()) && plane != "x-y") {
        std::cerr << "Invalid option specified. Only MIP, MinIP, and AIP are supported for x-y plane." << std::endl;
        return;
    }
    // Check if the output directory exists, and create it if it doesn't
    if (!fs::exists(path)) {
        if (!fs::create_directories(path)) { // create_directories æ éè¯¯æ¶åå»ºå¤çº§ç®å½
            std::cerr << "Error: Failed to create output directory." << std::endl;
            return;
        }
    }
    if (option) {
        std::visit([this, &path, &plane](auto &&arg) {
            using T = std::decay_t<decltype(arg)>;
            if constexpr (std::is_same_v<T, int>) {
                // Save a specific slice
                auto sliceData = Slice::getPlaneSlice(width, height, depth, data, plane, arg);
                std::string fullPath = path + "/slice_" + std::to_string(arg) + ".png";
                if (plane == "x-y") {
                    stbi_write_png(fullPath.c_str(), width, height, 1, sliceData.data(), width);
                } else if (plane == "x-z") {
                    stbi_write_png(fullPath.c_str(), width, depth, 1, sliceData.data(), width);
                } else if (plane == "y-z") {
                    stbi_write_png(fullPath.c_str(), height, depth, 1, sliceData.data(), height);
                }
            } else if constexpr (std::is_same_v<T, std::string>) {
                // Save a specific projection in the x-y plane, such as MIP, MinIP, AIP, or MedIP
                std::vector<unsigned char> projectionData;
                if (arg == "MIP") {
                    projectionData = Projection::maximumIntensityProjection(width, height, depth, data);
                } else if (arg == "MinIP") {
                    projectionData = Projection::minimumIntensityProjection(width, height, depth, data);
                } else if (arg == "AIP") {
                    projectionData = Projection::averageIntensityProjection(width, height, depth, data);
                } else if (arg == "MedIP") {
                    projectionData = Projection::medianIntensityProjection(width, height, depth, data);
                }
                std::string fullPath = path + "/" + arg + ".png";
                stbi_write_png(fullPath.c_str(), width, height, 1, projectionData.data(), width);
            }
        }, option.value());
    } else {
        // If no option is provided, save all slices based on the plane
        int numSlices = (plane == "x-y") ? depth : ((plane == "x-z") ? height : ((plane == "y-z") ? width : 0));
        for (int i = 1; i <= numSlices; ++i) {
            auto sliceData = Slice::getPlaneSlice(width, height, depth, data, plane, i);
            std::string fullPath = path + "/slice_" + std::to_string(i) + ".png";
            if (plane == "x-y") {
                stbi_write_png(fullPath.c_str(), width, height, 1, sliceData.data(), width);
            } else if (plane == "x-z") {
                // For x-z, height becomes the number of slices, width stays the same, and depth is the height of each slice.
                stbi_write_png(fullPath.c_str(), width, depth, 1, sliceData.data(), width);
            } else if (plane == "y-z") {
                // For y-z, width becomes the number of slices, height stays the same, and depth is the height of each slice.
                stbi_write_png(fullPath.c_str(), height, depth, 1, sliceData.data(), height);
            }
        }
    }
}
