// transform
void Filter::RGBtoHSV(float r, float g, float b, float &h, float &s, float &v)
{
    float K = 0.f;
    if (g < b)
    {
        std::swap(g, b);
        K = -1.f;
    }
    if (r < g)
    {
        std::swap(r, g);
        K = -2.f / 6.f - K;
    }
    float chroma = r - std::min(g, b);
    h = fabs(K + (g - b) / (6.f * chroma + 1e-20f));
    s = chroma / (r + 1e-20f);
    v = r;
}
void Filter::HSVtoRGB(float h, float s, float v, float &r, float &g, float &b)
{
    if (s == 0.f)
    {
        r = g = b = v;
        return;
    }
    int i = static_cast<int>(h * 6.f);
    float f = h * 6.f - i;
    float p = v * (1.f - s);
    float q = v * (1.f - f * s);
    float t = v * (1.f - (1.f - f) * s);
    switch (i % 6)
    {
    case 0:
        r = v, g = t, b = p;
        break;
    case 1:
        r = q, g = v, b = p;
        break;
    case 2:
        r = p, g = v, b = t;
        break;
    case 3:
        r = p, g = q, b = v;
        break;
    case 4:
        r = t, g = p, b = v;
        break;
    case 5:
        r = v, g = p, b = q;
        break;
    }
}
void Filter::RGBtoHSL(float r, float g, float b, float &h, float &s, float &l)
{
    float max = std::max({r, g, b}), min = std::min({r, g, b});
    l = (max + min) / 2.0f;
    if (max == min)
    {
        h = s = 0; // achromatic
    }
    else
    {
        float d = max - min;
        s = l > 0.5 ? d / (2.0 - max - min) : d / (max + min);
        if (max == r)
        {
            h = (g - b) / d + (g < b ? 6 : 0);
        }
        else if (max == g)
        {
            h = (b - r) / d + 2;
        }
        else if (max == b)
        {
            h = (r - g) / d + 4;
        }
        h /= 6.0f;
    }
}
void Filter::HSLtoRGB(float h, float s, float l, float &r, float &g, float &b)
{
    auto hue2rgb = [](float p, float q, float t) -> float
    {
        if (t < 0.f)
            t += 1.f;
        if (t > 1.f)
            t -= 1.f;
        if (t < 1.f / 6.f)
            return p + (q - p) * 6.f * t;
        if (t < 1.f / 2.f)
            return q;
        if (t < 2.f / 3.f)
            return p + (q - p) * (2.f / 3.f - t) * 6.f;
        return p;
    };
    if (s == 0.f)
    {
        r = g = b = l; // achromatic
    }
    else
    {
        float q = l < 0.5f ? l * (1.f + s) : l + s - l * s;
        float p = 2.f * l - q;
        r = hue2rgb(p, q, h + 1.f / 3.f);
        g = hue2rgb(p, q, h);
        b = hue2rgb(p, q, h - 1.f / 3.f);
    }
}
// greyscale
bool Filter::convertToGrayscale(Image *img_org, Image *img_filter)
{
    // image load fail or not color image
    if (img_org->getData() == nullptr || img_org->getChannels() < 3)
    {
        return false;
    }
    // save greyscle
    int pixelCount = img_org->getWidth() * img_org->getHeight();
    unsigned char *grayscaleData = (unsigned char *)malloc(pixelCount); // allocate memory
    if (!grayscaleData)
    {
        return false; // memory allocation fail
    }
    // greyscale
    for (int i = 0; i < pixelCount; ++i)
    {
        int index = i * img_org->getChannels();
        unsigned char r = img_org->getData()[index];
        unsigned char g = img_org->getData()[index + 1];
        unsigned char b = img_org->getData()[index + 2];
        unsigned char gray = static_cast<unsigned char>(round(0.2126f * r + 0.7152f * g + 0.0722f * b));
        grayscaleData[i] = gray;
    }
    // change
    img_filter->setWidth(img_org->getWidth());
    img_filter->setHeight(img_org->getHeight());
    img_filter->setData(grayscaleData);
    img_filter->setChannels(1);
    return true;
}
bool Filter::adjustBrightness(int value, Image *img_org, Image *img_filter)
{
    if (img_org->getData() == nullptr)
        return false;
    // storage
    int pixelCount = img_org->getWidth() * img_org->getHeight() * img_org->getChannels();
    unsigned char *brightnessdata = (unsigned char *)malloc(pixelCount); // allocate memory
    if (!brightnessdata)
    {
        return false; //
    }
    for (int i = 0; i < pixelCount; ++i)
    {
        int adjusted = static_cast<int>(img_org->getData()[i]) + value;
        brightnessdata[i] = static_cast<unsigned char>(std::max(0, std::min(255, adjusted)));
    }
    // return change
    img_filter->setWidth(img_org->getWidth());
    img_filter->setHeight(img_org->getHeight());
    img_filter->setData(brightnessdata);
    img_filter->setChannels(img_org->getChannels());
    return true;
}
int findMinCDF(const std::vector<int> &cdf)
{
    int minCDF = std::numeric_limits<int>::max(); // set max int
    for (int value : cdf)
    {
        if (value > 0 && value < minCDF)
        {
            minCDF = value;
        }
    }
    return (minCDF == std::numeric_limits<int>::max()) ? 0 : minCDF;
}
// calculate histogram and cdf
void calculateHistogramAndCDF(const std::vector<float> &vChannel, std::vector<int> &histogram, std::vector<int> &cdf)
{
    // calculate histogrim
    for (auto v : vChannel)
    {
        histogram[static_cast<int>(v * 255)]++;
    }
    // calculate CDF
    cdf[0] = histogram[0];
    for (size_t i = 1; i < histogram.size(); i++)
    {
        cdf[i] = cdf[i - 1] + histogram[i];
    }
    // cdf min
    int minCDF = *std::min_element(cdf.begin(), cdf.end(), [](int a, int b)
                                   { return a > 0 && a < b; });
    // int minCDF = findMinCDF(cdf);
    // apply
    for (auto &value : cdf)
    {
        if (value > 0)
        {
            value = static_cast<int>((static_cast<float>(value - minCDF) / (vChannel.size() - minCDF)) * 255);
        }
    }
}
void equalizeChannel(std::vector<float> &vChannel, const std::vector<int> &cdf)
{
    for (auto &v : vChannel)
    {
        int vIndex = static_cast<int>(v * 255);
        v = static_cast<float>(cdf[vIndex]) / 255.0f;
    }
}
// histogram equalization
bool Filter::histogramEqualization(Image *img_org, Image *img_filter, const std::string &choice)
{
    // change
    img_filter->setWidth(img_org->getWidth());
    img_filter->setHeight(img_org->getHeight());
    img_filter->setChannels(img_org->getChannels());
    // channel=1
    if (img_org->getChannels() == 1)
    {
        std::vector<float> channel(img_org->getWidth() * img_org->getHeight());
        for (int i = 0; i < img_org->getWidth() * img_org->getHeight(); i++)
        {
            channel[i] = img_org->getData()[i] / 255.0f;
        }
        std::vector<int> histogram(256, 0), cdf(256, 0);
        calculateHistogramAndCDF(channel, histogram, cdf);
        equalizeChannel(channel, cdf);
        for (int i = 0; i < img_org->getWidth() * img_org->getHeight(); i++)
        {
            img_filter->setDataAt(i, static_cast<unsigned char>(channel[i] * 255));
        }
        return true;
    }
    else if (img_org->getChannels() >= 3 && choice == "HSV")
    {
        // rgb to hsv
        std::vector<float> hChannel(img_org->getWidth() * img_org->getHeight()), sChannel(img_org->getWidth() * img_org->getHeight()), vChannel(img_org->getWidth() * img_org->getHeight());
        for (int i = 0; i < img_org->getWidth() * img_org->getHeight(); i++)
        {
            float r = img_org->getData()[i * img_org->getChannels()] / 255.0f;
            float g = img_org->getData()[i * img_org->getChannels() + 1] / 255.0f;
            float b = img_org->getData()[i * img_org->getChannels() + 2] / 255.0f;
            float h, s, v;
            RGBtoHSV(r, g, b, h, s, v);
            hChannel[i] = h;
            sChannel[i] = s;
            vChannel[i] = v;
        }
        std::vector<int> histogram(256, 0), cdf(256, 0);
        calculateHistogramAndCDF(vChannel, histogram, cdf);
        equalizeChannel(vChannel, cdf);
        // to rgb
        for (int i = 0; i < img_org->getWidth() * img_org->getHeight(); i++)
        {
            float r, g, b;
            HSVtoRGB(hChannel[i], sChannel[i], vChannel[i], r, g, b);
            img_filter->setDataAt(i * img_org->getChannels(), static_cast<unsigned char>(r * 255));
            img_filter->setDataAt(i * img_org->getChannels() + 1, static_cast<unsigned char>(g * 255));
            img_filter->setDataAt(i * img_org->getChannels() + 2, static_cast<unsigned char>(b * 255));
        }
        return true;
    }
    else if (img_org->getChannels() >= 3 && choice == "HSL")
    {
        // to HSV
        std::vector<float> hChannel(img_org->getWidth() * img_org->getHeight()), sChannel(img_org->getWidth() * img_org->getHeight()), vChannel(img_org->getWidth() * img_org->getHeight());
        for (int i = 0; i < img_org->getWidth() * img_org->getHeight(); i++)
        {
            float r = img_org->getData()[i * img_org->getChannels()] / 255.0f;
            float g = img_org->getData()[i * img_org->getChannels() + 1] / 255.0f;
            float b = img_org->getData()[i * img_org->getChannels() + 2] / 255.0f;
            float h, s, v;
            RGBtoHSL(r, g, b, h, s, v);
            hChannel[i] = h;
            sChannel[i] = s;
            vChannel[i] = v;
        }
        std::vector<int> histogram(256, 0), cdf(256, 0);
        calculateHistogramAndCDF(vChannel, histogram, cdf);
        equalizeChannel(vChannel, cdf);
        // to RGB
        for (int i = 0; i < img_org->getWidth() * img_org->getHeight(); i++)
        {
            float r, g, b;
            HSLtoRGB(hChannel[i], sChannel[i], vChannel[i], r, g, b);
            img_filter->setDataAt(i * img_org->getChannels(), static_cast<unsigned char>(r * 255));
            img_filter->setDataAt(i * img_org->getChannels() + 1, static_cast<unsigned char>(g * 255));
            img_filter->setDataAt(i * img_org->getChannels() + 2, static_cast<unsigned char>(b * 255));
        }
        return true;
    }
    else
    {
        return false;
    }
}
// threshold
bool Filter::thresholding(Image *img_org, Image *img_filter, const std::string &choice, int thresholdValue)
{
    img_filter->setWidth(img_org->getWidth());
    img_filter->setHeight(img_org->getHeight());
    img_filter->setChannels(img_org->getChannels());
    // channel=1
    if (img_org->getChannels() == 1)
    {
        img_filter->setData((unsigned char *)malloc(img_org->getWidth() * img_org->getHeight())); // åéåå­
        for (int i = 0; i < img_org->getWidth() * img_org->getHeight(); i++)
        {
            img_filter->setDataAt(i, img_org->getData()[i] >= thresholdValue ? 255 : 0);
        }
        return true;
    }
    //  color image:to HSV/HSLï¼and change VæL channel
    else if (img_org->getChannels() >= 3)
    {
        std::vector<float> hChannel(img_org->getWidth() * img_org->getHeight()), sChannel(img_org->getWidth() * img_org->getHeight()), vChannel(img_org->getWidth() * img_org->getHeight());
        for (int i = 0; i < img_org->getWidth() * img_org->getHeight(); i++)
        {
            float r = img_org->getData()[i * img_org->getChannels()] / 255.0f;
            float g = img_org->getData()[i * img_org->getChannels() + 1] / 255.0f;
            float b = img_org->getData()[i * img_org->getChannels() + 2] / 255.0f;
            float h, s, v;
            if (choice == "HSV")
            {
                RGBtoHSV(r, g, b, h, s, v);
            }
            else
            { // "HSL"
                RGBtoHSL(r, g, b, h, s, v);
            }
            hChannel[i] = h;
            sChannel[i] = s;
            vChannel[i] = v >= thresholdValue / 255.0f ? 1.0f : 0.0f;
        }
        // to RGB
        img_filter->setData((unsigned char *)malloc(img_org->getWidth() * img_org->getHeight() * img_org->getChannels())); // åéåå­
        for (int i = 0; i < img_org->getWidth() * img_org->getHeight(); i++)
        {
            float r, g, b;
            if (choice == "HSV")
            {
                HSVtoRGB(hChannel[i], sChannel[i], vChannel[i], r, g, b);
            }
            else
            { // "HSL"
                HSLtoRGB(hChannel[i], sChannel[i], vChannel[i], r, g, b);
            }
            img_filter->setDataAt(i * img_org->getChannels(), static_cast<unsigned char>(r * 255));
            img_filter->setDataAt(i * img_org->getChannels() + 1, static_cast<unsigned char>(g * 255));
            img_filter->setDataAt(i * img_org->getChannels() + 2, static_cast<unsigned char>(b * 255));
            if (img_org->getChannels() == 4)
            { // keep alpha
                img_filter->setDataAt(i * img_org->getChannels() + 3, img_org->getData()[i * img_org->getChannels() + 3]);
            }
        }
        return true;
    }
    return false;
}
// noise
bool Filter::addSaltAndPepperNoise(Image *img_org, Image *img_filter, float noisePercentage)
{
    // random seed
    srand(time(nullptr)); // initial generator
    int pixelCount = img_org->getWidth() * img_org->getHeight();
    int noisePixels = static_cast<int>(pixelCount * noisePercentage);
    // change
    img_filter->setWidth(img_org->getWidth());
    img_filter->setHeight(img_org->getHeight());
    img_filter->setChannels(img_org->getChannels());
    // copy original image
    unsigned char *newData = (unsigned char *)malloc(img_org->getWidth() * img_org->getHeight() * img_org->getChannels());
    memcpy(newData, img_org->getData(), img_org->getWidth() * img_org->getHeight() * img_org->getChannels());
    img_filter->setData(newData);
    for (int i = 0; i < noisePixels; ++i)
    {
        int idx = rand() % pixelCount; // random choose a pixel position
        bool pepper = rand() % 2 == 0; // add white or black
        // for each channel
        for (int c = 0; c < img_org->getChannels(); ++c)
        {
            img_filter->setDataAt(idx * img_org->getChannels() + c, pepper ? 255 : 0);
        }
    }
    return true;
}
// 2d blur
Image Filter::applyMedianBlur(Image &image, int kernelSize)
{
    int width = image.getWidth();
    int height = image.getHeight();
    int channels = image.getChannels();
    // Create a new Image object for the result
    Image resultImage;
    resultImage.loadData(new unsigned char[width * height * channels], width, height, channels);
    // Apply median blur for each channel
    for (int y = 0; y < height; ++y)
    {
        for (int x = 0; x < width; ++x)
        {
            for (int c = 0; c < channels; ++c)
            {
                auto kernel = getMedianKernel(image.getData(), width, height, channels, x, y, kernelSize, c);
                resultImage.getData()[y * width * channels + x * channels + c] = kernel[kernel.size() / 2];
            }
        }
    }
    return resultImage;
}
Image Filter::applyBoxBlur(const Image &image, int kernelSize)
{
    int width = image.getWidth();
    int height = image.getHeight();
    int channels = image.getChannels();
    // Use the new constructor
    Image resultImage(width, height, channels);
    int halfKernel = kernelSize / 2;
    for (int y = 0; y < height; y++)
    {
        for (int x = 0; x < width; x++)
        {
            std::vector<long> sum(channels, 0);
            int count = 0;
            for (int ky = -halfKernel; ky <= halfKernel; ky++)
            {
                for (int kx = -halfKernel; kx <= halfKernel; kx++)
                {
                    int nx = x + kx;
                    int ny = y + ky;
                    if (nx >= 0 && nx < width && ny >= 0 && ny < height)
                    {
                        auto pixel = image.getPixel(nx, ny);
                        for (int c = 0; c < channels; c++)
                        {
                            sum[c] += pixel[c];
                        }
                        count++;
                    }
                }
            }
            std::vector<unsigned char> newPixel(channels);
            for (int c = 0; c < channels; c++)
            {
                newPixel[c] = static_cast<unsigned char>(sum[c] / count);
            }
            resultImage.setPixel(x, y, newPixel);
        }
    }
    return resultImage;
}
std::vector<unsigned char> Filter::getMedianKernel(unsigned char *data, int width, int height, int channels, int x, int y, int kernelSize, int channel)
{
    std::vector<unsigned char> kernel;
    int halfKernel = kernelSize / 2;
    for (int ky = -halfKernel; ky <= halfKernel; ++ky)
    {
        for (int kx = -halfKernel; kx <= halfKernel; ++kx)
        {
            int nx = x + kx;
            int ny = y + ky;
            if (nx >= 0 && nx < width && ny >= 0 && ny < height)
            {
                kernel.push_back(data[ny * width * channels + nx * channels + channel]);
            }
        }
    }
    std::sort(kernel.begin(), kernel.end());
    return kernel;
}
void Filter::applyGaussian2D(Image &img, int kernelSize, double sigma)
{
    unsigned char *data = img.getData();
    int w = img.getWidth();
    int h = img.getHeight();
    int c = img.getChannels();
    std::vector<unsigned char> output(data, data + w * h * c);
    Gaussian2D filter(sigma, kernelSize);
    filter.applyGaussian2DFilter(output, w, h, c);
    img.updateData(output);
}
// edge detection
void Filter::applyEdgeDetection(Image &inputImage, const std::string &choice, Image &outputImage)
{
    int width = inputImage.getWidth(), height = inputImage.getHeight();
    unsigned char *img = inputImage.getData(); // Assume inputImage is already in the correct format (grayscale for simplicity)
    // mode map
    std::unordered_map<std::string, int> mapping = {
        {"Sobel", 1},
        {"Prewitt", 2},
        {"Scharr", 3},
        {"RobertsCross", 4}};
    int choice_num = mapping[choice];
    if (img == nullptr)
    {
        throw std::runtime_error("Input image data is null.");
    }
    std::vector<unsigned char> outputImageData(width * height, 0);
    float *gradX = new float[width * height];
    float *gradY = new float[width * height];
    memset(gradX, 0, width * height * sizeof(float));
    memset(gradY, 0, width * height * sizeof(float));
    int maxSize = (choice_num == 4) ? 2 : 3;
    std::vector<std::vector<int>> gx(maxSize, std::vector<int>(maxSize));
    std::vector<std::vector<int>> gy(maxSize, std::vector<int>(maxSize));
    // Initialize kernels based on the filter type
    switch (choice_num)
    {
    case 1:
        gx = {{-1, 0, 1}, {-2, 0, 2}, {-1, 0, 1}};
        gy = {{-1, -2, -1}, {0, 0, 0}, {1, 2, 1}};
        break;
    case 2:
        gx = {{-1, 0, 1}, {-1, 0, 1}, {-1, 0, 1}};
        gy = {{-1, -1, -1}, {0, 0, 0}, {1, 1, 1}};
        break;
    case 3:
        gx = {{-3, 0, 3}, {-10, 0, 10}, {-3, 0, 3}};
        gy = {{-3, -10, -3}, {0, 0, 0}, {3, 10, 3}};
        break;
    case 4:
        gx = {{1, 0}, {0, -1}};
        gy = {{0, 1}, {-1, 0}};
        break;
    }
    // Apply convolution
    for (int y = 0; y < height - (maxSize - 1); y++)
    {
        for (int x = 0; x < width - (maxSize - 1); x++)
        {
            float pixelX = 0.0f, pixelY = 0.0f;
            for (int ky = 0; ky < maxSize; ky++)
            {
                for (int kx = 0; kx < maxSize; kx++)
                {
                    int pixelVal = img[(y + ky) * width + (x + kx)];
                    pixelX += gx[ky][kx] * pixelVal;
                    pixelY += gy[ky][kx] * pixelVal;
                }
            }
            float mag = std::sqrt(pixelX * pixelX + pixelY * pixelY);
            outputImageData[y * width + x] = static_cast<unsigned char>(std::min(255.0f, mag));
        }
    }
    // Assuming outputImage is prepared for the dimensions and format
    outputImage.loadData(outputImageData.data(), width, height, 1); // Load the processed data into the output image
    delete[] gradX;
    delete[] gradY;
}

