double calculateVariance(const unsigned char* imageData, int dataSize) {
    if (dataSize <= 0) return 0.0;
    double sum = 0.0;
    for (int i = 0; i < dataSize; ++i) {
        sum += imageData[i];
    }
    double mean = sum / dataSize;

    double variance = 0.0;
    for (int i = 0; i < dataSize; ++i) {
        variance += (imageData[i] - mean) * (imageData[i] - mean);
    }
    variance /= dataSize;
    return variance;
}
// Adjusted function to check if the edge filter correctly identifies edges by comparing variance
bool checkEdgeDetection(const unsigned char* originalImageData, const unsigned char* filteredImageData, int width, int height, int channels) {
    int dataSize = width * height * channels;
    double originalVariance = calculateVariance(originalImageData, dataSize);
    double filteredVariance = calculateVariance(filteredImageData, dataSize);
    // Expect the variance to increase after applying the edge filter due to enhanced edges
    return filteredVariance > originalVariance;
}
