          return this.normals[closestIndex];
        }
      }
      function distToSegmentSquared(point, v, w) {
        const l2 = p5.Vector.dist(v, w);
        if (l2 === 0) return p5.Vector.dist(point, v);
        let t =
          ((point.x - v.x) * (w.x - v.x) + (point.y - v.y) * (w.y - v.y)) /
          l2 ** 2;
        t = Math.max(0, Math.min(1, t));
