pub fn routes(repository: MongoTodoRepository) -> impl Filter<Extract = (impl warp::Reply,), Error = warp::Rejection> + Clone {
    let create_todo = warp::post()
        .and(warp::path("todos"))
        .and(warp::body::json())
        .and(with_repository(repository.clone()))
        .and_then(create_todo);
    let get_todos = warp::get()
        .and(warp::path("todos"))
        .and(with_repository(repository.clone()))
        .and_then(get_todos);
    let get_todo = warp::get()
        .and(warp::path("todos").and(warp::path::param()))
        .and(with_repository(repository.clone()))
        .and_then(get_todo);
    let update_todo = warp::put()
        .and(warp::path("todos").and(warp::path::param()))
        .and(warp::body::json())
        .and(with_repository(repository.clone()))
        .and_then(update_todo);
    let delete_todo = warp::delete()
        .and(warp::path("todos").and(warp::path::param()))
        .and(with_repository(repository))
        .and_then(delete_todo);
    create_todo.or(get_todos).or(get_todo).or(update_todo).or(delete_todo)
}
