    private int getDominantColor(Bitmap bitmap) {
        Palette palette = Palette.from(bitmap).generate();
        Palette.Swatch dominantSwatch = palette.getDominantSwatch();
        if (dominantSwatch != null) {
            return dominantSwatch.getRgb();
        } else {
            return Color.BLACK;
        }
