    // Add all objects to the temporary canvas with their original scale and position
    canvas.getObjects().forEach((obj) => {
      if (!obj.excludeFromExport) {
        const originalObj = fabric.util.object.clone(obj);
        const originalTransformMatrix = originalObj.calcTransformMatrix();
        // Reset the transform matrix
        originalObj.transformMatrix = [1, 0, 0, 1, 0, 0];
        // Apply the necessary transformations manually
        originalObj.set({
